    if |s| < |suffix| then {
        return false;
    }
    return s[|s|-|suffix|..|s|] == suffix;
}

function Contains(s: string, substr: string): bool {
    for i := 0 to |s| - |substr|
        invariant 0 <= i <= |s| - |substr| + 1
    {
        if s[i..i+|substr|] == substr then {
            return true;
        }
    }
    return false;
}

function Find(s: string, substr: string): int 
    requires Contains(s, substr)
{
    for i := 0 to |s| - |substr|
        invariant 0 <= i <= |s| - |substr| + 1
    {
        if s[i..i+|substr|] == substr then {
            return i;
        }
    }
    // This should never be reached due to precondition
    return -1;
}

function split(s: string, delimiter: char): seq<string> {
    var result: seq<string> := [];
    var current := "";

    for i := 0 to |s| - 1
        invariant |result| * (|delimiter| as nat) <= i
    {
        if s[i] == delimiter then {
            result := result + [current];
            current := "";
        } else {
            current := current + [s[i]];
        }
    }

    if current != "" then {
        result := result + [current];
    }

    return result;
}

function Join(words: seq<string>, delimiter: string): string {
    if |words| == 0 then {
        return "";
    }

    var result := words[0];
    for i := 1 to |words| - 1
        invariant |result| >= |words[0]|
    {
        result := result + delimiter + words[i];
    }
    return result;
}

