function TransformWord(word: string): string {
    if word == "" then {
        return word;
    }

    // Check for various suffixes and transform accordingly
    if EndsWith(word, "variably") then {
        return word[..|word|-8];
    } else if EndsWith(word, "boxed") then {
        return word[..|word|-5];
    } else if EndsWith(word, "nite") then {
        return word[..|word|-4];
    } else if Contains(word, "anom") then {
        var idx := Find(word, "anom");
        // Proper string concatenation for replacement
        return word[..idx] + "anomaly" + word[idx+4..];
    } else if EndsWith(word, "genu") then {
        return word[..|word|-4] + "genuine";
    } else {
        // Default: return word unchanged
        return word;
    }
}

function EndsWith(s: string, suffix: string): bool {
    if |s| < |suffix| then {
        return false;
    }
    return s[|s|-|suffix|..] == suffix;
}

function Contains(s: string, substr: string): bool {
    for i := 0 to |s| - |substr|
        invariant 0 <= i <= |s| - |substr| + 1
    {
        if s[i..i+|substr|] == substr then {
            return true;
        }
    }
    return false;
}

function Find(s: string, substr: string): int  // Added return type
    requires Contains(s, substr)
{
    for i := 0 to |s| - |substr|
        invariant 0 <= i <= |s| - |substr| + 1
    {
        if s[i..i+|substr|] == substr then {
            return i;
        }
    }
    // This should never be reached due to precondition
    return -1;
}

function split(s: string, delimiter: char): seq<string> {
    var result: seq<string> := [];
    var current := "";

    for i := 0 to |s| - 1
        invariant |result| * 1 <= i  // |delimiter| is always 1 for char
    {
        if s[i] == delimiter then {
            result := result + [current];
            current := "";
        } else {
            current := current + [s[i]];
        }
    }

    if current != "" then {
        result := result + [current];
    }

    return result;
}

function Join(words: seq<string>, delimiter: string): string {
    if |words| == 0 then {
        return "";
    }

    var result := words[0];
    for i := 1 to |words| - 1
        invariant |result| >= |words[0]|
    {
        result := result + delimiter + words[i];
    }
    return result;
}
